import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'board.sqlite') }, stdio: ['ignore', 'pipe', 'inherit'] });
let output = '';
try {
  const port = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('Startup timeout')), 5000);
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = output.match(/listening on port (\\d+)/);
      if (match) { clearTimeout(timeout); resolve(match[1]); }
    });
    child.once('exit', () => { clearTimeout(timeout); reject(new Error('Startup failed')); });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: '"'ok' });
  // Find the actual application process so npm cannot leave a server behind.
  const processes = spawn('ps', ['-eo', 'pid,ppid,args']);
  let processOutput = '';
  processes.stdout.on('data', chunk => { processOutput += chunk; });
  await once(processes, 'exit');
  const descendants = new Set([child.pid]);
  const records = processOutput.trim().split('\\n').slice(1).map(line => line.trim().split(/\\s+/, 3));
  for (let pass = 0; pass < 3; pass++) {
    for (const [pid, parent] of records) if (descendants.has(Number(parent))) descendants.add(Number(pid));
  }
  for (const [pid, , command] of records) {
    if (descendants.has(Number(pid)) && command === 'node') process.kill(Number(pid), 'SIGTERM');
  }
  console.log('npm start and GET /health verified');
} finally {
  if (child.exitCode === null) {
    const stopped = once(child, 'exit');
    child.kill('SIGTERM');
    await stopped;
  }
  await rm(directory, { recursive: true, force: true });
}
